<?php
namespace EventFlow\Presentation\Api;
use EventFlow\Application\Import\{ImportRowStatus,ImportStatus};use EventFlow\Application\Persistence\EventScope;
final readonly class ImportAdministrationRequestMapper
{public function scope(RestRequest$r):EventScope{return new EventScope($this->routeId($r,'event_id'));}public function jobId(RestRequest$r):int{return$this->routeId($r,'import_job_id');}/** @return array{int,?int,?ImportStatus} */public function jobs(RestRequest$r):array{$status=$r->query('status');$typed=$status===null?null:ImportStatus::tryFrom($status);if($status!==null&&$typed===null)throw new RequestInputException('validation_failed');return[$this->queryInt($r->query('limit'),50,1,100),$r->query('after')===null?null:$this->queryInt($r->query('after'),null,1,PHP_INT_MAX),$typed];}/** @return array{int,?int,?ImportRowStatus} */public function rows(RestRequest$r):array{$status=$r->query('status');$typed=$status===null?null:ImportRowStatus::tryFrom($status);if($status!==null&&$typed===null)throw new RequestInputException('validation_failed');return[$this->queryInt($r->query('limit'),100,1,500),$r->query('after')===null?null:$this->queryInt($r->query('after'),null,1,PHP_INT_MAX),$typed];}public function requireEmptyBody(RestRequest$r):void{if($r->json()!==[])throw new RequestInputException('validation_failed');}private function routeId(RestRequest$r,string$n):int{$candidate=$r->route($n);if($candidate===null||!ctype_digit($candidate))throw new RequestInputException('resource_not_found');$value=filter_var($candidate,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($value===false)throw new RequestInputException('resource_not_found');return$value;}private function queryInt(?string$v,?int$d,int$min,int$max):int{if($v===null)return$d??throw new RequestInputException('validation_failed');if(!preg_match('/^[1-9][0-9]*$/',$v))throw new RequestInputException('validation_failed');$value=filter_var($v,FILTER_VALIDATE_INT,['options'=>['min_range'=>$min,'max_range'=>$max]]);if($value===false)throw new RequestInputException('validation_failed');return$value;}}
